local s_vsh = [[
attribute vec2 vPosition;
varying vec2 vUv;
void main()
{
    gl_Position = vec4(vPosition, 0.0, 1.0);
    //An opportunism code. Do not use it unless you know what it means.
    vUv = (vPosition.xy + 1.0) / 2.0;
}
]]

local s_fsh = [[
#ifdef GL_FRAGMENT_PRECISION_HIGH
precision highp float;
#else
precision mediump float;
#endif

uniform sampler2D inputImageTexture;
uniform float dir; // 0-2pi   水滴运动方向
uniform float speed; //0-0.5  水滴运动速度

uniform float densityMin;  
uniform float densityMax;

uniform vec2  uMainTexSize;
uniform float uTime;

varying vec2 vUv;

float smoothing = 0.01;
float ballradius = 0.;
float metaPow = 3.0;
float densityEvolution = 0.4;
float rotationSpeed = 0.0;
float distortion = 0.0;
float nstrenght = 1.0;
float nsize = 2.0;
vec3 lightColor = vec3(1, 1, 1);
float f0 = .0;
float fp = 5.;

float saturate1(float x)
{
    return clamp(x, 0.0, 1.0);
}
vec2 rotuv(vec2 uv, float angle, vec2 center)
{    
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, -s, s, c) * (uv - center) + center;
}
float random(float n)
{
    return fract(sin(dot(vec2(n,n) ,vec2(12.9898,78.233))) * 43758.5453);  
}  

float metaBall(vec2 uv)
{
    return saturate1(length(fract(uv) - vec2(0.5)) * 2.);
}

float metaNoiseRaw(vec2 uv, vec2 moveSpeed, float density, float uTime)
{
    float v = 0.5;
    float metaball0 = 1.;
    
    for(int i = 0; i < 8; i++)
    {
        float inc = float(i) + 1.0;
        float r1 = random(114.514*inc);
        float s1 = uTime*(r1-0.5)*rotationSpeed;
        vec2 f1 = uTime*moveSpeed*r1;
        vec2 c1 = vec2(random(31.2*inc), random(90.2*inc))*100.0 + s1;   
        vec2 uv1 = rotuv(uv*(1.0 - r1 * v), r1*120.0 + s1, c1) + f1 - metaball0*distortion;    
        float metaball1 = saturate1(metaBall(uv1)*density);
        
        metaball0 *= metaball1;
    }

    return pow(metaball0, metaPow);
}

float metaNoise(vec2 uv, vec2 moveSpeed, float aspect, float uTime)
{ 
    float density = mix(densityMin,densityMax,sin(uTime*densityEvolution)*0.5+0.5);
    density *= pow(1. / aspect, .2);
    return 1.0 - smoothstep(ballradius, ballradius+smoothing, metaNoiseRaw(uv, moveSpeed, density, uTime));
}

vec4 calculateNormals(vec2 uv, vec2 moveSpeed, float s, float aspect, float uTime)
{
    float offsetX = nsize*s / uMainTexSize.x;
    float offsetY = nsize*s / uMainTexSize.y;
    vec2 ovX = vec2(offsetX, 0.0);
    vec2 ovY = vec2(0.0, offsetY);
    
    float X = (metaNoise(uv - ovX, moveSpeed, aspect, uTime) - metaNoise(uv + ovX, moveSpeed, aspect, uTime)) * nstrenght;
    float Y = (metaNoise(uv - ovY, moveSpeed, aspect, uTime) - metaNoise(uv + ovY, moveSpeed, aspect, uTime)) * nstrenght;

    float Z = sqrt(1.0 - saturate1(dot(vec2(X,Y), vec2(X,Y))));
    
    float c = abs(X+Y);
    return normalize(vec4(X,Y,Z,c));
}

void main() 
{
    float aspect = uMainTexSize.x / uMainTexSize.y;

    vec2 moveSpeed = vec2(sin(dir), cos(dir)) * speed;

    vec2 uv2 = vUv;
    uv2.x *= aspect;

    uv2 += uTime*moveSpeed;

    vec4 n = calculateNormals(uv2, moveSpeed, 1., aspect, uTime);
    vec3 lDir = normalize(vec3(1.0, 1.0, 0.0));
    
    float l = max(0.0, dot(n.xyz, lDir));  

    vec4 tex = texture2D(inputImageTexture, vUv + n.xy);
    vec4 tex2 = texture2D(inputImageTexture, vUv + n.xy + vec2(0.005, 0));  
    vec4 tex3 = texture2D(inputImageTexture, vUv + n.xy + vec2(-0.005, 0));

    float noise = metaNoise(uv2, moveSpeed, aspect, uTime);

    float fresnel = (f0 + (1. - f0) * pow(1. - noise, fp)) * smoothstep(1., .7, 1. - noise);

    vec3 col = mix(tex.xyz, (vec3(tex2.r * .5 + tex.r * .5, tex.g, tex3.b * .5 + tex.b * .5) + l * lightColor) * 1.3, noise);
    col *= 1. - fresnel;
    col += smoothstep(.5, 1., (1. - noise)) * noise * tex.r;

    gl_FragColor = vec4(col, 1); 
}
]]

